253	    public void saveOwner(Owner owner) throws DataAccessException {
254	        if (owner.getTelephone() != null) {
255	            owner.setTelephone(normalizeTelephone(owner.getTelephone()));
256	        }
257	        if (owner.getEmail() != null) {
258	            owner.setEmail(normalizeEmail(owner.getEmail()));
259	        }
260	        if (owner.getAddress() != null) {
261	            owner.setAddress(normalizeAddress(owner.getAddress()));
262	        }
263	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
264	        owner.setRegistrationDate(rollToBusinessDay(effectiveDate));
265	        if (owner.getCustomerCode() == null) {
266	            owner.setCustomerCode(generateCustomerCode(owner));
267	        }
268	        boolean creating = owner.isNew();
269	        if (creating) {
270	            owner.setNamesakeCount(countNamesakes(owner));
271	            assertDailyCapacity(owner);
272	            assertCityCapacity(owner);
273	        }
274	        assertTelephoneUnique(owner, owner.getTelephone());
275	        assertEmailUnique(owner, owner.getEmail());
276	        List<Owner> household = findHouseholdMembers(owner);
277	        assertHouseholdAllowed(owner, household);
278	        assignHousehold(owner, household);
279	        ownerRepository.save(owner);
280	        populateHouseholdSize(owner);
281	        if (creating) {
282	            AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
283	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
284	                owner.getMembershipLevel());
285	        }
286	    }
287	
288	    /**
289	     * Build a {@code customerCode} formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the
290	     * upper-cased first three letters of the owner's city, LAST3 the upper-cased first three
291	     * letters of {@code lastName}, and NNNN is a per-city 4-digit zero-padded sequence equal to
292	     * one more than the number of owners already in that city.
293	     */
294	    private String generateCustomerCode(Owner owner) {
295	        String cityPrefix = prefix3(owner.getCity());
296	        String lastNamePrefix = prefix3(owner.getLastName());
297	        long sequence = countOwnersInCity(owner.getCity()) + 1L;
298	        return String.format("%s-%s-%04d", cityPrefix, lastNamePrefix, sequence);
299	    }
300	
301	    private static String prefix3(String value) {
302	        return value.substring(0, Math.min(3, value.length())).toUpperCase(Locale.ROOT);
303	    }
304	
305	    /** Maximum number of owners permitted in a single city. */
306	    private static final long CITY_OWNER_LIMIT = 50L;
307	
308	    /**
309	     * Rejects creating {@code owner} when its city already contains {@link #CITY_OWNER_LIMIT} or
310	     * more owners, so no city can grow beyond the capacity limit.
311	     *
312	     * @throws CityOwnerLimitException if the owner's city is already at capacity
313	     */
314	    private void assertCityCapacity(Owner owner) {
315	        if (owner.getCity() == null) {
316	            return;
317	        }
318	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
319	            throw new CityOwnerLimitException(owner.getCity(), CITY_OWNER_LIMIT);
320	        }
321	    }
322	
323	    /**
324	     * Rolls {@code date} forward to the next business day when it falls on a weekend: a Saturday or
325	     * Sunday becomes the following Monday. Business days (Monday to Friday) are returned unchanged.
326	     */
327	    private static LocalDate rollToBusinessDay(LocalDate date) {
328	        switch (date.getDayOfWeek()) {
329	            case SATURDAY:
330	                return date.plusDays(2);
331	            case SUNDAY:
332	                return date.plusDays(1);
333	            default:
334	                return date;
335	        }
336	    }
337	
338	    /** Maximum number of owners permitted to be registered on a single day. */
339	    private static final long DAILY_OWNER_LIMIT = 100L;
340	
341	    /** More than this many owners registered on a single day raises the bulk-signup warning. */
342	    private static final long BULK_SIGNUP_THRESHOLD = 80L;
343	
344	    /**
345	     * Reports whether more than {@link #BULK_SIGNUP_THRESHOLD} owners have already been registered
346	     * today, reusing the same daily accumulation as the per-day create limit ({@link
347	     * #assertDailyCapacity}).
348	     */
349	    @Override
350	    @Transactional(readOnly = true)
351	    public boolean isBulkSignupWarningActive() throws DataAccessException {
352	        return countOwnersRegisteredOn(LocalDate.now()) > BULK_SIGNUP_THRESHOLD;
353	    }
354	
355	    /**
356	     * Rejects creating {@code owner} when its {@code registrationDate} (defaulted to today for a new
357	     * owner) already has {@link #DAILY_OWNER_LIMIT} or more owners registered, so no more than that
358	     * many owners can be created on any single day.
359	     *
360	     * @throws DailyOwnerLimitException if the owner's registration day is already at capacity
361	     */
362	    private void assertDailyCapacity(Owner owner) {
363	        LocalDate date = owner.getRegistrationDate();
364	        if (date == null) {
365	            return;
366	        }
367	        if (countOwnersRegisteredOn(date) >= DAILY_OWNER_LIMIT) {
368	            throw new DailyOwnerLimitException(date, DAILY_OWNER_LIMIT);
369	        }
370	    }
371	
372	    private long countOwnersRegisteredOn(LocalDate date) {
373	        return ownerRepository.findAll().stream()
374	                .filter(existing -> date.equals(existing.getRegistrationDate()))
375	                .count();
376	    }
377	
378	    private long countOwnersInCity(String city) {
379	        String normalized = normalizeHouseholdValue(city);
380	        return ownerRepository.findAll().stream()
381	                .filter(existing -> normalized.equals(normalizeHouseholdValue(existing.getCity())))
382	                .count();
383	    }
384	
385	    /**
386	     * Counts the existing owners that share both {@code firstName} and {@code lastName} with the
387	     * given new {@code owner}, compared case-insensitively (with incidental whitespace collapsed).
388	     * The owner being created is not itself persisted yet, so the result is the number of namesakes
389	     * that already existed before this create.
390	     */
391	    private int countNamesakes(Owner owner) {
392	        String firstName = normalizeHouseholdValue(owner.getFirstName());
393	        String lastName = normalizeHouseholdValue(owner.getLastName());
394	        int count = 0;
395	        for (Owner existing : ownerRepository.findAll()) {
396	            if (!existing.getId().equals(owner.getId())
397	                    && firstName.equals(normalizeHouseholdValue(existing.getFirstName()))
398	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))) {
399	                count++;
400	            }
401	        }
402	        return count;
403	    }
404	
405	    private static String normalizeEmail(String email) {
406	        return email == null ? null : email.toLowerCase(Locale.ROOT);
407	    }
408	
409	    /** Common street-type abbreviations expanded during address normalization. */
410	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
411	        "ST", "STREET",
412	        "RD", "ROAD",
413	        "AVE", "AVENUE");
414	
415	    /**
416	     * Canonicalizes a postal address: trims and collapses runs of whitespace into a single space,
417	     * upper-cases, and expands common street-type abbreviations (ST->STREET, RD->ROAD, AVE->AVENUE)
418	     * as whole words. Returns {@code null} for a {@code null} input and an empty string when the
419	     * address is blank once whitespace is stripped, so the required-field check sees the normalized
420	     * form.
421	     */
422	    private static String normalizeAddress(String address) {
423	        if (address == null) {
424	            return null;
425	        }
426	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
427	        if (collapsed.isEmpty()) {
428	            return "";
429	        }
430	        String[] tokens = collapsed.split(" ");
431	        StringBuilder sb = new StringBuilder(collapsed.length());
432	        for (int i = 0; i < tokens.length; i++) {
433	            if (i > 0) {
434	                sb.append(' ');
435	            }
436	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
437	        }
438	        return sb.toString();
439	    }
440	
441	    private static String normalizeTelephone(String telephone) {
442	        return telephone == null ? null : E164Telephone.toE164(telephone);
443	    }
444	
445	    /**
446	     * Rejects saving {@code owner} when its {@code normalized} telephone is already used by any
447	     * other owner, so no two owners can share a telephone number.
448	     *
449	     * @throws DuplicateTelephoneException if another owner already has the same normalized telephone
450	     */
451	    private void assertTelephoneUnique(Owner owner, String normalized) {
452	        if (normalized == null || normalized.isEmpty()) {
453	            return;
454	        }
455	        for (Owner existing : ownerRepository.findAll()) {
456	            if (!existing.getId().equals(owner.getId())
457	                    && normalized.equals(normalizeTelephone(existing.getTelephone()))) {
458	                throw new DuplicateTelephoneException(normalized);
459	            }
460	        }
461	    }
462	
463	    /**
464	     * Rejects saving {@code owner} when its {@code normalized} (lower-cased) email is already used by
465	     * any other owner, so no two owners can share an email address.
466	     *
467	     * @throws DuplicateEmailException if another owner already has the same normalized email
468	     */
469	    private void assertEmailUnique(Owner owner, String normalized) {
470	        if (normalized == null || normalized.isEmpty()) {
471	            return;
472	        }
473	        for (Owner existing : ownerRepository.findAll()) {
474	            if (!existing.getId().equals(owner.getId())
475	                    && normalized.equals(normalizeEmail(existing.getEmail()))) {
476	                throw new DuplicateEmailException(normalized);
477	            }
478	        }
479	    }
480	
481	    /**
482	     * Returns the existing owners that share both {@code lastName} (compared case-insensitively with
483	     * collapsed whitespace) and the normalized {@code address} with a new {@code owner} — i.e. the
484	     * members of the household it would join. Returns an empty list for an update to an existing
485	     * owner or when either household value is blank, so household rules only apply to genuine new
486	     * members.
487	     */
488	    private List<Owner> findHouseholdMembers(Owner owner) {
489	        if (!owner.isNew()) {
490	            return List.of();
491	        }
492	        String lastName = normalizeHouseholdValue(owner.getLastName());
493	        String address = normalizeHouseholdAddress(owner.getAddress());
494	        if (lastName.isEmpty() || address.isEmpty()) {
495	            return List.of();
496	        }
497	        List<Owner> household = new ArrayList<>();
498	        for (Owner existing : ownerRepository.findAll()) {
499	            if (!existing.getId().equals(owner.getId())
500	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))
501	                    && address.equals(normalizeHouseholdAddress(existing.getAddress()))) {
502	                household.add(existing);
503	            }
504	        }
505	        return household;
506	    }
507	
508	    /**
509	     * Pure guard: rejects creating {@code owner} when it would join a non-empty {@code household}
510	     * without acknowledging the shared household via {@link Owner#isSharesHousehold()}. Returns
511	     * without side effects otherwise.
512	     *
513	     * @throws DuplicateHouseholdException if another owner already lives at the same household and
514	     *                                     the request does not acknowledge the shared household
515	     */
516	    private void assertHouseholdAllowed(Owner owner, List<Owner> household) {
517	        if (!household.isEmpty() && !owner.isSharesHousehold()) {
518	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
519	        }
520	    }
521	
522	    /**
523	     * Assigns household membership when {@code owner} joins a non-empty {@code household}: the new
524	     * owner and every matching existing member that lacks one are given the same stable
525	     * {@code householdId}, and any updated existing members are persisted. No-op when the household
526	     * is empty.
527	     */
528	    private void assignHousehold(Owner owner, List<Owner> household) {
529	        if (household.isEmpty()) {
530	            return;
531	        }
532	        String householdId = resolveHouseholdId(owner, household);
533	        owner.setHouseholdId(householdId);
534	        for (Owner existing : household) {
535	            if (existing.getHouseholdId() == null || existing.getHouseholdId().isBlank()) {
536	                existing.setHouseholdId(householdId);
537	                ownerRepository.save(existing);
538	            }
539	        }
540	    }
541	
542	    /**
543	     * Stamps {@code owner} with the number of owners sharing its {@code householdId} (see {@link
544	     * Owner#getHouseholdSize()}), so presentation code can derive the membership tier without
545	     * reaching into the data store. A {@code null} owner or one without a household id is left at
546	     * size 0.
547	     */
548	    private void populateHouseholdSize(Owner owner) {
549	        if (owner == null) {
550	            return;
551	        }
552	        String householdId = owner.getHouseholdId();
553	        if (householdId == null || householdId.isBlank()) {
554	            owner.setHouseholdSize(0);
555	            return;
556	        }
557	        int count = 0;
558	        for (Owner existing : ownerRepository.findAll()) {
559	            if (householdId.equals(existing.getHouseholdId())) {
560	                count++;
561	            }
562	        }
563	        owner.setHouseholdSize(count);
564	    }
565	
566	    /**
567	     * Stamps every owner in {@code owners} with its household size in a single pass over the data
568	     * store, so a list/page of owners is counted without a per-owner query.
569	     *
570	     * @see #populateHouseholdSize(Owner)
571	     */
572	    private void populateHouseholdSizes(Collection<Owner> owners) {
573	        if (owners.isEmpty()) {
574	            return;
575	        }
576	        Map<String, Integer> sizes = new HashMap<>();
577	        for (Owner existing : ownerRepository.findAll()) {
578	            String householdId = existing.getHouseholdId();
579	            if (householdId != null && !householdId.isBlank()) {
580	                sizes.merge(householdId, 1, Integer::sum);
581	            }
582	        }
583	        for (Owner owner : owners) {
584	            String householdId = owner.getHouseholdId();
585	            owner.setHouseholdSize(householdId == null ? 0 : sizes.getOrDefault(householdId, 0));
586	        }
587	    }
588	
589	    /**
590	     * Returns the {@code householdId} shared by a household: the first non-blank identifier already
591	     * carried by an existing member, or otherwise a freshly derived stable identifier for the
592	     * joining {@code owner}'s normalized lastName and address.
593	     */
594	    private String resolveHouseholdId(Owner owner, List<Owner> household) {
595	        for (Owner existing : household) {
596	            if (existing.getHouseholdId() != null && !existing.getHouseholdId().isBlank()) {
597	                return existing.getHouseholdId();
598	            }
599	        }
600	        return generateHouseholdId(normalizeHouseholdValue(owner.getLastName()),
601	            normalizeHouseholdAddress(owner.getAddress()));
602	    }
603	
604	    /**
605	     * Derives a stable {@code householdId} formatted {@code 'HH-<12 upper-hex>'} from the SHA-256
606	     * digest of the normalized {@code lastName} and {@code address}, so all owners in the same
607	     * household deterministically share the same identifier.
608	     */
609	    private static String generateHouseholdId(String lastName, String address) {
610	        try {
611	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
612	            byte[] hash = digest.digest((lastName + "\u0000" + address).getBytes(StandardCharsets.UTF_8));
613	            StringBuilder sb = new StringBuilder();
614	            for (int i = 0; i < 6; i++) {
615	                sb.append(String.format("%02X", hash[i]));
616	            }
617	            return "HH-" + sb;
618	        } catch (NoSuchAlgorithmException e) {
619	            throw new IllegalStateException("SHA-256 not available", e);
620	        }
621	    }
622	
623	    /**
624	     * Normalizes a household comparison value by trimming, collapsing runs of whitespace into a
625	     * single space and lower-casing, so comparisons ignore case and incidental whitespace.
626	     */
627	    private static String normalizeHouseholdValue(String value) {
628	        if (value == null) {
629	            return "";
630	        }
631	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
632	    }
633	
634	    /**
635	     * Household comparison value for an address: the canonical {@link #normalizeAddress(String)}
636	     * form (never {@code null}), so duplicate detection and the shared household id compare
637	     * addresses using the same normalized representation that is stored and returned.
638	     */
639	    private static String normalizeHouseholdAddress(String address) {
640	        String normalized = normalizeAddress(address);
641	        return normalized == null ? "" : normalized;
642	    }
643	
644	    @Override
645	    @Transactional(readOnly = true)
646	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
647	        Collection<Owner> owners = ownerRepository.findByLastName(lastName);
648	        populateHouseholdSizes(owners);
649	        return owners;
650	    }
651	
652	    @Override
653	    @Transactional(readOnly = true)
654	    public Collection<Visit> findVisitsByPetId(int petId) {
655	        return visitRepository.findByPetId(petId);
656	    }
657	
658	    @Override
659	    @Transactional(readOnly = true)
660	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
661	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
662	    }
663	
664	    private <T> T findEntityById(Supplier<T> supplier) {
665	        try {
666	            return supplier.get();
667	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
668	            // Just ignore not found exceptions for Jdbc/Jpa realization
669	            return null;
670	        }
671	    }
672	
673	}
